    /**
     * Valida el encabezado del token para asegurar que el algoritmo es compatible.
     * 
     * La función verifica si el campo 'alg' en el encabezado contiene 'HS256'.
     */
    public static boolean validateAlgorithm(String header) {
        // Dividir el encabezado en campos utilizando ':' como separador
        String[] parts = header.split(":");

        // Buscar el campo 'alg'
        for (String part : parts) {
            if (part.trim().equals("alg")) {
                // Verificar si el valor del campo 'alg' es 'HS256'
                return parts[parts.length - 1].trim().equals("HS256");
            }
        }

        // Si no se encuentra el campo 'alg' o su valor no es 'HS256', devolver false
        return false;
    }
}
