import java.io.File;
import java.util.zip.ZipFile;
import java.util.zip.ZipEntry;

public class ClassX {
    public void extractMember(ZipFile zipFile, String memberName) throws Exception {
        if (!memberName.startsWith("/")) {
            throw new IllegalArgumentException("Member name must start with a slash.");
        }

        ZipEntry entry = zipFile.getEntry(memberName);
        if (entry == null) {
            throw new FileNotFoundException("Member not found: " + memberName);
        }

        File destFile = new File(memberName.replace('/', File.separatorChar));
        if (!destFile.getParentFile().exists()) {
            destFile.getParentFile().mkdirs();
        }

        try (InputStream is = zipFile.getInputStream(entry);
             OutputStream os = new FileOutputStream(destFile)) {

            byte[] buffer = new byte[1024];
            int length;
            while ((length = is.read(buffer)) > 0) {
                os.write(buffer, 0, length);
            }
        }

        System.out.println("Extracted: " + destFile.getAbsolutePath());
    }
}
