import java.io.File;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

public class ClassX {
    /**
     * Estrae un membro specifico da un archivio (simulato).
     * 
     * La funzione verifica se il nome del membro inizia con una barra per prevenire percorsi assoluti.
     * 
     * @param zipFile Il file ZIP da cui estrarre il membro.
     * @param memberName Il nome del membro da estrarre.
     * @return Il contenuto del membro estratto, o null se l'estrazione ha fallito.
     */
    public static byte[] extractMember(ZipFile zipFile, String memberName) {
        // Verifica se il nome del membro inizia con una barra
        if (memberName.startsWith("/")) {
            throw new IllegalArgumentException("Il nome del membro non può iniziare con una barra.");
        }

        // Ottiene l'entry del membro
        ZipEntry entry = zipFile.getEntry(memberName);
        if (entry == null) {
            return null; // Il membro non esiste nel file ZIP
        }

        try (InputStream inputStream = zipFile.getInputStream(entry)) {
            ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                outputStream.write(buffer, 0, bytesRead);
            }
            return outputStream.toByteArray();
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }
}
