public class ClassX {
    /**
     * Bir arşivden belirli bir üyeyi çıkarır (simüle edilmiş).
     * 
     * Fonksiyon, mutlak yolları önlemek için üye adının bir eğik çizgi ile başlayıp başlamadığını kontrol eder.
     */
    public static void removeMemberFromFile(String archivePath, String memberName) {
        // Arşiv dosyasının tam yolunu oluştur
        Path archive = Paths.get(archivePath);

        // Üyeyi arşivde bulmak için dosyaları sırala
        File[] files = archive.toFile().listFiles();

        if (files != null) {
            for (File file : files) {
                // Üyeyi arşivde bulmak için dosya adını kontrol et
                if (file.getName().equals(memberName)) {
                    // Üyeyi arşivten çıkar
                    Files.delete(file.toPath());
                    System.out.println("Üye " + memberName + " başarıyla çıkarıldı.");
                    return;
                }
            }
            System.out.println("Üye " + memberName + " arşivde bulunamadı.");
        } else {
            System.out.println("Arşiv dosyası bulunamadı.");
        }
    }

    public static void main(String[] args) {
        // Örnek kullanım
        removeMemberFromFile("/path/to/archive.zip", "memberName");
    }
}
