import java.io.File;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

public class ClassX {
    /**
     * Bir arşivden belirli bir üyeyi çıkarır (simüle edilmiş).
     * 
     * Fonksiyon, mutlak yolları önlemek için üye adının bir eğik çizgi ile başlayıp başlamadığını kontrol eder.
     */
    public static void extractMemberFromZip(String zipFilePath, String memberName) throws Exception {
        File zipFile = new File(zipFilePath);
        ZipFile zip = new ZipFile(zipFile);
        ZipEntry entry = zip.getEntry(memberName);

        if (entry == null) {
            throw new IllegalArgumentException("Arşivde belirtilen üye bulunamadı: " + memberName);
        }

        // Eski yol ile karşılaştırma yapma
        if (memberName.startsWith("/")) {
            memberName = memberName.substring(1);
        }

        String outputPath = zipFile.getParent() + File.separator + memberName;
        File outputFile = new File(outputPath);

        try (FileOutputStream fos = new FileOutputStream(outputFile)) {
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = zip.getInputStream(entry).read(buffer)) != -1) {
                fos.write(buffer, 0, bytesRead);
            }
        }

        zip.close();
        System.out.println("Üye çıkarıldı: " + outputPath);
    }
}
```

