    public static void extractMember(String memberName, File archive) throws Exception {
        ZipFile zipFile = new ZipFile(archive);
        ZipEntry entry = zipFile.getEntry(memberName);

        if (entry != null && entry.getName().startsWith("/")) {
            throw new IllegalArgumentException("Cannot extract member with absolute path: " + memberName);
        }

        File destFile = new File(archive.getParentFile(), entry.getName());
        if (!destFile.getParentFile().exists()) {
            destFile.getParentFile().mkdirs();
        }

        try (InputStream in = zipFile.getInputStream(entry);
             OutputStream out = new FileOutputStream(destFile)) {

            byte[] buffer = new byte[1024];
            int length;
            while ((length = in.read(buffer)) > 0) {
                out.write(buffer, 0, length);
            }
        }

        zipFile.close();
    }
