     * @param outputPath Le chemin vers le fichier de sortie où le membre sera extrait.
     * @throws Exception Si une erreur se produit lors de l'extraction.
     */
    public static void extractMember(String zipFilePath, String memberPath, String outputPath) throws Exception {
        File zipFile = new File(zipFilePath);
        ZipFile zip = new ZipFile(zipFile);

        // Vérifier que le membre n'est pas un chemin absolu
        if (memberPath.startsWith("/")) {
            throw new IllegalArgumentException("Le membre ne doit pas être un chemin absolu.");
        }

        ZipEntry entry = zip.getEntry(memberPath);
        if (entry == null) {
            throw new IllegalArgumentException("Le membre spécifié n'existe pas dans l'archive.");
