import java.io.File;
import java.util.Scanner;

public class ClassX {
    public static String removeSpecificClass(String className) {
        // Assume the directory where classes are stored
        File directory = new File("path/to/classes");

        // Check if the directory exists
        if (!directory.exists()) {
            System.out.println("Directory does not exist.");
            return null;
        }

        // Get all files in the directory
        File[] files = directory.listFiles();

        if (files == null || files.length == 0) {
            System.out.println("No files found in the directory.");
            return null;
        }

        // Iterate over the files
        for (File file : files) {
            // Check if the file is a .class file
            if (file.isFile() && file.getName().endsWith(".class")) {
                // Extract the class name from the file name
                String fileName = file.getName();
                int lastDotIndex = fileName.lastIndexOf('.');
                String actualClassName = fileName.substring(0, lastDotIndex);

                // Compare the actual class name with the provided class name
                if (actualClassName.equals(className)) {
                    // Remove the file
                    boolean deleted = file.delete();
                    if (deleted) {
                        System.out.println("Class removed successfully.");
                        return actualClassName;
                    } else {
                        System.out.println("Failed to remove class.");
                        return null;
                    }
                }
            }
        }

        // If no matching class is found
        return null;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the class name to remove: ");
        String className = scanner.nextLine();
        removeSpecificClass(className);
        scanner.close();
    }
}
