import java.net.URL;

public class ClassX {
    public static String fetchContent(URL url) {
        if (url == null) {
            throw new IllegalArgumentException("URL must not be null");
        }

        try {
            // Attempt to open a connection to the URL
            java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            // Read the response
            int responseCode = connection.getResponseCode();
            if (responseCode != 200) {
                throw new RuntimeException("Failed to retrieve content: HTTP code " + responseCode);
            }

            StringBuilder content = new StringBuilder();
            try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.InputStreamReader(connection.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    content.append(line).append("\n");
                }
            }

            // Remove leading and trailing whitespace
            String trimmedContent = content.toString().trim();

            // Check if the content is empty after trimming
            if (trimmedContent.isEmpty()) {
                throw new RuntimeException("No content retrieved");
            }

            return trimmedContent;
        } catch (Exception e) {
            throw new RuntimeException("Error fetching content from URL", e);
        }
    }
}
