            // Validate the URL to ensure it's not null or has invalid characters
            if (url == null || !isValidURL(url)) {
                throw new IllegalArgumentException("Invalid URL provided.");
            }

            // Use HttpURLConnection to fetch the content from the URL
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();

            // Check if the request was successful
            int responseCode = connection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                throw new RuntimeException("Failed to retrieve content. HTTP response code: " + responseCode);
            }

            // Get the input stream from the connection
            java.io.InputStream inputStream = connection.getInputStream();
            java.util.Scanner scanner = new java.util.Scanner(inputStream).useDelimiter("\\A");

            // Read the entire content as a string
            String content = scanner.hasNext() ? scanner.next() : "";

            // Close the scanner and connection
            scanner.close();
            connection.disconnect();

            return content;
        } catch (Exception e) {
            // Handle exceptions appropriately
            e.printStackTrace();
            return null;
        }
    }

    private boolean isValidURL(URL url) {
        try {
            // Check if the URL is well-formed
