import java.net.URL;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class ClassX {
    /**
     * Récupère le contenu d'une URL générée après avoir validé l'hôte.
     * 
     * Cette fonction assainit l'hôte en vérifiant la présence de caractères invalides tels que des espaces.
     * @param hostname Le nom d'hôte à valider et assainir.
     * @return L'URL générée avec un nom d'hôte assaini.
     * @throws IllegalArgumentException Si le nom d'hôte contient des caractères invalides.
     */
    public static URL getSecureURL(String hostname) throws IllegalArgumentException {
        // Vérifier si le nom d'hôte contient des caractères invalides
        if (hostname.contains(" ")) {
            throw new IllegalArgumentException("Le nom d'hôte ne doit pas contenir d'espace.");
        }

        // Assainir le nom d'hôte en utilisant une méthode de hachage pour éviter les attaques par injection de script
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = md.digest(hostname.getBytes());
            String hashedHostname = bytesToHex(hashBytes);
            return new URL("https://secure-" + hashedHostname + ".com");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Impossible de générer le hash du nom d'hôte.", e);
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
```

