    public static String fetchContent(String url) {
        try {
            // Validiere den Host
            String host = validateHost(url);

            // Erstelle die URL mit dem validierten Host
            URL validatedUrl = new URL("http://" + host + url.substring(url.indexOf("/")));

            // Öffne die URL und lese den Inhalt
            return fetchFromURL(validatedUrl);
        } catch (MalformedURLException e) {
            System.out.println("Invalid URL: " + e.getMessage());
            return null;
        }
