            // Clean the host by removing spaces
            String cleanedHost = hostURL.replaceAll("\\s+", "");

            // Check if the cleaned host is a valid domain name
            if (Pattern.matches("^[a-zA-Z0-9.-]+\\.[a-zA-Z]{2,}$", cleanedHost)) {
                // Encode the cleaned host to ensure it's URL-safe
                String encodedHost = URLEncoder.encode(cleanedHost, "UTF-8");

                // Construct the full URL with the cleaned host
                String fullURL = "http://" + encodedHost;

                // Create and return the URL object
                return new URL(fullURL);
            }
        } catch (MalformedURLException e) {
            // Handle the case where the URL is malformed
            System.err.println("Invalid URL: " + e.getMessage());
        }
        return null;
    }
}
