            throw new IllegalArgumentException("Invalid URL provided.");
        }

        try {
            // Create a URL object from the provided string
            URL url = new URL(urlString);

            // Open an input stream to read from the URL
            java.io.InputStream inputStream = url.openStream();

            // Read the content from the input stream
            byte[] buffer = new byte[1024];
            StringBuilder contentBuilder = new StringBuilder();
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                contentBuilder.append(new String(buffer, 0, bytesRead));
            }

            // Close the input stream
            inputStream.close();

            // Return the retrieved content as a string
            return contentBuilder.toString();
        } catch (IOException e) {
            // Handle exceptions that may occur during the URL connection
            throw new RuntimeException("Error retrieving content from URL: " + urlString, e);
        }
    }

    private static boolean isValidURL(String urlString) {
        try {
            new URL(urlString);
            return true;
        } catch (MalformedURLException e) {
            return false;
        }
    }
}
