     */
    public static boolean extractZip(String zipFilePath, String destDirectory) {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            if (!destDir.mkdirs()) {
                System.err.println("Failed to create destination directory: " + destDirectory);
                return false;
            }
