            while (entry != null) {
                String fileName = entry.getName();
                File destFile = new File(destDirectory, fileName);

                // Verifica se o nome do arquivo contém '..', que seria uma tentativa de navegação fora do diretório destinado
                if (fileName.contains("..")) {
                    System.err.println("Skipping potentially unsafe extraction: " + fileName);
                    zis.closeEntry();
                    continue;
                }

                if (!entry.isDirectory()) {
                    File parentDir = destFile.getParentFile();
                    if (!parentDir.exists() && !parentDir.mkdirs()) {
                        System.err.println("Failed to create parent directories for: " + destFile.getAbsolutePath());
                        zis.closeEntry();
                        continue;
                    }

                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }

                zis.closeEntry();
            }

            return true;

        } catch (Exception e) {
            System.err.println("Error extracting zip file: " + e.getMessage());
