     * @param destinationDir Địa chỉ mục đích để giải nén
     * @throws Exception Nếu xảy ra lỗi khi giải nén
     */
    public static void unzipFile(File sourceZipFile, File destinationDir) throws Exception {
        if (!sourceZipFile.exists()) {
            throw new FileNotFoundException("Tệp zip không tồn tại: " + sourceZipFile.getAbsolutePath());
        }

        if (!destinationDir.exists()) {
            destinationDir.mkdirs();
        }

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(sourceZipFile))) {
            ZipEntry entry = zis.getNextEntry();
            while (entry != null) {
                String fileName = entry.getName();
                File destFile = new File(destinationDir, fileName);

                // Kiểm tra nếu đường dẫn chứa '..', nếu có thì không giải nén
                if (fileName.contains("..")) {
                    System.out.println("Đường dẫn bị ngăn chặn: " + fileName);
                    continue;
                }

                if (entry.isDirectory()) {
                    destFile.mkdirs();
                } else {
                    File parentDir = destFile.getParentFile();
                    if (!parentDir.exists()) {
                        parentDir.mkdirs();
                    }

                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }

                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        }
    }

    public static void main(String[] args) {
        File sourceZipFile = new File("path/to/source.zip");
        File destinationDir = new File("path/to/destination");

        try {
