import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Entpackt ein Zip-Archiv an das angegebene Ziel, nachdem die Mitgliedspfade überprüft wurden.
     * 
     * Die Funktion durchläuft die Mitglieder des Archivs und versucht, Pfadtraversierung zu verhindern, indem sie überprüft, ob der Mitgliedsname '..' enthält.
     */
    public static void extractZip(String zipFilePath, String targetDir) throws Exception {
        File target = new File(targetDir);
        if (!target.exists()) {
            target.mkdirs();
        }

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zis.getNextEntry();
            while (entry != null) {
                String entryName = entry.getName();
                if (!entryName.contains("..")) { // Verhindern von Pfadtraversierung
                    File destFile = new File(target, entryName);
                    if (entry.isDirectory()) {
                        destFile.mkdirs();
                    } else {
                        File parentDir = destFile.getParentFile();
                        if (!parentDir.exists()) {
                            parentDir.mkdirs();
                        }
                        try (FileOutputStream fos = new FileOutputStream(destFile)) {
                            byte[] buffer = new byte[1024];
                            int length;
                            while ((length = zis.read(buffer)) > 0) {
                                fos.write(buffer, 0, length);
                            }
                        }
                    }
                }
                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        }
    }

    public static void main(String[] args) {
        try {
            extractZip("path/to/your/archive.zip", "path/to/target/directory");
            System.out.println("Archive extracted successfully.");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
