            image/jpeg=image/jpeg-viewer;
            application/pdf=application/pdf-viewer;
        """;

        // Split the mailcap content by semicolons
        String[] entries = mailcapContent.split(";");

        for (String entry : entries) {
            String[] parts = entry.trim().split("=");
            if (parts.length == 2) {
                String mimeTypePattern = parts[0].trim();
                String application = parts[1].trim();

                // Use regex to match the MIME type
