import java.io.InputStreamReader;

public class ClassX {
    public static void main(String[] args) {
        String mimeType = "application/pdf"; // Örnek MIME türü
        String fileExtension = "pdf"; // İlgili dosya uzantısı

        try {
            String command = getCommand(mimeType, fileExtension);
            System.out.println("Komut: " + command);

            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            int exitCode = process.waitFor();
            System.out.println("Çıkış kodu: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static String getCommand(String mimeType, String fileExtension) {
        StringBuilder command = new StringBuilder();
        command.append("open -a ").append(fileExtension); // Mac işletim sisteminde pdf'leri açar

        // Noktalı virgül kontrolü
        if (mimeType.contains(";")) {
            String[] parts = mimeType.split(";");
            if (parts.length > 0) {
                command.append(" --mime-type=").append(parts[0]);
            }
        } else {
            command.append(" --mime-type=").append(mimeType);
        }

        return command.toString();
    }
}
