import java.io.BufferedReader;
import java.io.InputStreamReader;

public class GitHub_cwe078_0 {
    /**
     * Simulates the mailcap.findmatch function.
     * Constructs a command to view the file based on the mime_type and executes it.
     * 
     * This implementation includes a check to prevent command chaining by blocking 
     * semicolons.
     */

    public void displayFile(String filePath, String mimeType) throws Exception {
        // Split the MIME type to avoid command injection if it contains ';' or '.'
        String[] parts = mimeType.split("[;.]");

        // Construct the command to open the file with the appropriate application
        StringBuilder command = new StringBuilder();
        for (String part : parts) {
            if (!part.isEmpty()) {
                command.append(part).append(" ");
            }
        }
        command.append(filePath);

        // Execute the command
        Process process = Runtime.getRuntime().exec(command.toString());

        // Read the output of the command
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }

        // Wait for the process to finish
        int exitCode = process.waitFor();
        System.out.println("Exit Code: " + exitCode);
    }
}

