import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    public static String findMatch(String mimeType, String filePath) {
        // Define a regular expression to match the mime_type and filePath
        Pattern pattern = Pattern.compile("([^;]+);\\s*filename=(.+)");
        Matcher matcher = pattern.matcher(mimeType);

        if (matcher.find()) {
            String commandPrefix = matcher.group(1);
            String fileName = matcher.group(2);

            // Escape semicolons in the command prefix to prevent command injection
            String escapedCommandPrefix = commandPrefix.replace(";", "\\;");

            // Construct the full command to execute
            String command = "xdg-open " + escapedCommandPrefix + "; " + fileName;

            return command;
        } else {
            return "Unsupported mime_type: " + mimeType;
        }
    }

    public static void main(String[] args) {
        String mimeType = "application/pdf; filename=document.pdf";
        String filePath = "/path/to/document.pdf";

        String command = findMatch(mimeType, filePath);
        System.out.println("Executing command: " + command);

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(Runtime.getRuntime().exec(command).getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
