     * @param filePath The path to the file.
     * @return The command to execute, or null if no command is found.
     */
    private static String getOpenCommand(String mimeType, String filePath) {
        // Simple example: check for common MIME types and return the corresponding command
        switch (mimeType.toLowerCase()) {
            case "text/plain":
                return "open " + filePath; // Assuming Unix-like system
            case "image/jpeg":
                return "display " + filePath; // Assuming Unix-like system
            case "application/pdf":
                return "evince " + filePath; // Assuming Ubuntu/Debian
            default:
                return null; // No specific command found for this MIME type
        }
    }
}
