import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    public static void main(String[] args) {
        String mimeType = "text/plain"; // Esempio di mime_type
        String filePath = "/path/to/file.txt"; // Esempio di percorso del file

        try {
            String command = getCommand(mimeType, filePath);
            Runtime.getRuntime().exec(command);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static String getCommand(String mimeType, String filePath) throws Exception {
        String[] mimeTypes = mimeType.split(";");
        String[] extensions = new String[mimeTypes.length];
        for (int i = 0; i < mimeTypes.length; i++) {
            extensions[i] = mimeTypes[i].split("/")[1];
        }

        String[] commands = {
            "xdg-open", // Common on Linux
            "open",    // Common on macOS
            "start"   // Common on Windows
        };

        for (String command : commands) {
            for (String extension : extensions) {
                String[] cmd = {command, filePath};
                if (isSafeCommand(cmd)) {
                    return String.join(" ", cmd);
                }
            }
        }

        throw new Exception("No safe command found for the given mime type and file path.");
    }

    private static boolean isSafeCommand(String[] cmd) {
        // Basic check to prevent shell injection
        StringBuilder sb = new StringBuilder();
        for (String arg : cmd) {
            sb.append(arg).append(" ");
        }
        String command = sb.toString().trim();
        return !command.contains(";") && !command.contains("|") && !command.contains("&") && !command.contains("<") && !command.contains(">");
    }
}
```

