import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Simuliert die Funktion mailcap.findmatch. 
     * Konstruiert einen Befehl, um die Datei basierend auf dem mime_type anzuzeigen, und führt ihn aus.
     * 
     * Diese Implementierung enthält eine Überprüfung, um das Verketten von Befehlen zu verhindern, indem Semikolons blockiert werden.
     */
    public void displayFileByMimeType(String mimeType, String filePath) {
        // Überprüfen, ob die Datei existiert
        if (!new java.io.File(filePath).exists()) {
            System.out.println("Die Datei existiert nicht.");
            return;
        }

        // Konstruktion des Befehls zur Anzeige der Datei
        StringBuilder command = new StringBuilder("file -i " + filePath);
        if (mimeType != null) {
            command.append(" | grep ").append(mimeType);
