public class ClassX {
    /**
     * Pingt einen angegebenen Host.
     * 
     * Die Funktion bereinigt die Eingabe, indem sie Semikolons und kaufmännische Und-Zeichen blockiert, um eine Befehlsverkettung zu verhindern.
     * @param hostName Der Name des Hosts, der getinged werden soll.
     * @return Der Ping-Resultat als String.
     */
    public static String pingHost(String hostName) {
        // Bereinige die Eingabe
        hostName = hostName.replaceAll(";", "").replaceAll("&", "");

        try {
            // Erstelle ein BufferedReader zum Lesen von Daten vom Terminal
            BufferedReader reader = new BufferedReader(new InputStreamReader(Runtime.getRuntime().exec("ping " + hostName).getInputStream()));

            // Lese den Output des Pings aus
            StringBuilder result = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                result.append(line).append("\n");
            }

            return result.toString();
        } catch (Exception e) {
            return "Fehler beim Pingen: " + e.getMessage();
        }
    }

    public static void main(String[] args) {
        String host = "example.com";
        String pingResult = pingHost(host);
        System.out.println("Ping-Resultat für " + host + ":\n" + pingResult);
    }
}
