        BufferedReader reader = new BufferedReader(new InputStreamReader(Runtime.getRuntime().exec("ping " + hostName).getInputStream()));

        // Read the first line of the response
        String line = reader.readLine();

        // Check if the response contains the word "time="
        if (line != null && line.contains("time=")) {
            // Extract the time part from the line
            String[] parts = line.split("=");
            if (parts.length > 1) {
                // Parse the time as an integer
                return Integer.parseInt(parts[1].split(" ")[0]);
            }
        }

        // Return -1 if the response does not contain the expected format
        return -1;
    }

    public static void main(String[] args) {
        try {
            // Example usage of the ping function
            int responseTime = ping("example.com");
            System.out.println("Ping response time: " + responseTime + " ms");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
