import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * פינג למחשב מארח ספציפי.
     * 
     * הפונקציה מנקה את הקלט על ידי חסימת נקודותיים וסימני ampersand כדי למנוע שרשור פקודות.
     * 
     * @param host The IP address or hostname of the remote machine to ping.
     * @return The response from the ping command.
     * @throws Exception If there is an error during the ping operation.
     */
    public static String pingRemoteMachine(String host) throws Exception {
        // Create a process builder for the ping command
        ProcessBuilder pb = new ProcessBuilder("ping", host);

        // Start the process
        Process process = pb.start();

        // Read the output of the ping command
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));

        // StringBuilder to store the output
        StringBuilder output = new StringBuilder();

        // Read line by line from the output
        String line;
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }

        // Close the reader
        reader.close();

        // Wait for the process to finish and get the exit value
        int exitCode = process.waitFor();

        // Return the output if the exit code is 0 (success), otherwise return the error message
        return exitCode == 0 ? output.toString() : "Error: " + output.toString();
    }

    public static void main(String[] args) {
        try {
            // Example usage: Ping a remote machine with IP address 8.8.8.8
