     * @throws Exception Jika terjadi kesalahan saat mengirim ping
     */
    public String sendPing(String host) throws Exception {
        // Membaca input dari pengguna
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.print("Masukkan host yang ingin di-ping: ");
        String targetHost = reader.readLine().trim();

