import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Pinge um host especificado.
     * 
     * A função sanitiza a entrada bloqueando ponto e vírgula e e comercial para evitar encadeamento de comandos.
     * 
     * @param host O nome do host ou endereço IP a ser pingado.
     * @return true se o host está ativo, false caso contrário.
     */
    public static boolean pingHost(String host) {
        try {
            // Sanitiza a entrada
            String sanitizedHost = host.replaceAll("[.;]", "");

            // Cria uma instância de InetAddress
            InetAddress address = InetAddress.getByName(sanitizedHost);

            // Verifica se o host está ativo
            return address.isReachable(1000); // Tempo máximo de espera em milissegundos
        } catch (UnknownHostException e) {
            System.err.println("Host não encontrado: " + host);
            return false;
        } catch (Exception e) {
            System.err.println("Erro ao pingar o host: " + host);
            e.printStackTrace();
            return false;
        }
    }

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Uso: java ClassX <host>");
            return;
        }

        String host = args[0];
        if (pingHost(host)) {
            System.out.println("O host " + host + " está ativo.");
        } else {
            System.out.println("O host " + host + " está inativo.");
        }
    }
}
