     * @param host Hôte à pinger.
     * @return Résultat de la commande ping.
     * @throws Exception Si une erreur se produit lors de la pinging.
     */
    public static String pingHost(String host) throws Exception {
        // Nettoyage de l'entrée pour éviter les problèmes dans les commandes
        String cleanedHost = host.replace(";", "").replace("\"", "");

        // Construction de la commande ping
        String command = "ping " + cleanedHost;

