import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Belirtilen bir ana bilgisayara ping atar.
     * 
     * Fonksiyon, komut zincirlemesini önlemek için girişte noktalı virgülleri ve ampersandları engelleyerek veriyi temizler.
     * 
     * @param ipAddress Ana bilgisayarın IP adresi.
     * @return Ping işleminin sonuçları.
     * @throws Exception Eğer ping işlemi başarısız olursa veya bir hata oluşursa.
     */
    public static String ping(String ipAddress) throws Exception {
        // Komut zincirlemesini önlemek için veriyi temizler
        String sanitizedIpAddress = ipAddress.replaceAll("[.,&]", "");

        // "ping" komutunu çalıştır
        ProcessBuilder pb = new ProcessBuilder("ping", "-c", "4", sanitizedIpAddress);
        Process process = pb.start();

        // Çıktıyı okur
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuilder result = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            result.append(line).append("\n");
        }

        // Hata çıkışı kontrol eder
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new Exception("Ping işlemi başarısız oldu. Exit code: " + exitCode);
        }

        return result.toString();
    }

    public static void main(String[] args) {
        try {
            String ipAddress = "8.8.8.8"; // Google DNS IP adresi
            String pingResult = ping(ipAddress);
            System.out.println("Ping sonuçları:");
            System.out.println(pingResult);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
