     */
    public String renderTemplate(String template, Map<String, String> userInputs) throws IOException {
        StringBuilder sanitizedTemplate = new StringBuilder();
        Map<String, String> safeInputs = new HashMap<>();

        // Sanitize user inputs by replacing Jinja2 variable delimiters
        for (Map.Entry<String, String> entry : userInputs.entrySet()) {
            String key = entry.getKey();
            String value = entry.getValue().replaceAll("\\{\\{", "").replaceAll("\\}\\}", "");
            safeInputs.put(key, value);
        }

        // Replace placeholders in the template with sanitized inputs
        int index = 0;
        while (index < template.length()) {
            int start = template.indexOf("{{", index);
            int end = template.indexOf("}}", index);

            if (start != -1 && end != -1) {
                String placeholder = template.substring(start + 2, end);
                String safeValue = safeInputs.get(placeholder);

                if (safeValue != null) {
                    sanitizedTemplate.append(safeValue);
                } else {
                    sanitizedTemplate.append("{{" + placeholder + "}}"); // Leave placeholder unchanged if not found
                }

                index = end + 2; // Move past the placeholder
            } else {
                sanitizedTemplate.append(template.substring(index));
                break;
            }
        }

        return sanitizedTemplate.toString();
    }

