        while (true) {
            int startBlockIndex = input.indexOf("{{", startIndex);
            if (startBlockIndex == -1) {
                break;
            }
            int endBlockIndex = input.indexOf("}}", startBlockIndex + 2);

            if (endBlockIndex == -1) {
                break;
            }

            // Voeg de inhoud van het blok toe aan het resultaat
            result.append(input, startIndex, startBlockIndex);
            result.append("<!-- {{...}} -->");

            startIndex = endBlockIndex + 2;
        }

        // Voeg de rest van de input toe
        result.append(input, startIndex, input.length());

        return result.toString();
    }
}
