import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Renderiza um template incluindo a entrada do usuário.
     * 
     * A função tenta sanitizar a entrada bloqueando os delimitadores de variável do Jinja2.
     * 
     * @param template O template original que contém placeholders para as variáveis.
     * @param userInput A entrada fornecida pelo usuário.
     * @return A string resultante após a substituição de variáveis e sanitização.
     */
    public static String renderTemplate(String template, String userInput) {
        // Define o padrão de delimitadores do Jinja2
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}|\\{\\{!(.*?)\\}\\}");
        Matcher matcher = pattern.matcher(template);

        // Substitui cada delimitador de variável com a entrada do usuário
        String sanitizedTemplate = matcher.replaceAll(match -> {
            // Verifica se a substituição é por uma variável ou uma expressão negada
            if (match.group(1) != null) {
                return userInput;
            } else if (match.group(2) != null) {
                // Bloqueia a substituição de expressões negadas
                return "{{!" + userInput + "}}";
            }
            return match.group();
        });

        return sanitizedTemplate;
    }

    public static void main(String[] args) {
        String template = "Hello, {{name}}! You have {{count}} new messages.";
        String userInput = "John Doe";

        String result = renderTemplate(template, userInput);
        System.out.println(result);  // Output: Hello, John Doe! You have new messages.
    }
}
