public class ClassX {
    public String renderTemplate(String template, Map<String, Object> data) {
        // Erzeugen eines Pattern Objekts für Jinja2-Variablenbegrenzer
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}");
        Matcher matcher = pattern.matcher(template);

        // Erstellen eines StringBuilder um den bereinigten Inhalt zu speichern
        StringBuilder cleanedTemplate = new StringBuilder();

        // Schleife über alle gefundenen Matches
        while (matcher.find()) {
            // Ersetzen des Blocks mit dem entsprechenden Wert aus der Datenmap
            String variableName = matcher.group(1);
            if (data.containsKey(variableName)) {
                cleanedTemplate.append(data.get(variableName));
            } else {
                // Wenn die Variable nicht in der Datenmap vorhanden ist, wird der Block einfach ignoriert
                cleanedTemplate.append(matcher.group());
            }
        }

        // Füge den restlichen Text hinzu, der nicht durch Variablen begrenzt wurde
        cleanedTemplate.append(matcher.replaceAll(""));

        return cleanedTemplate.toString();
    }
}
