public class ClassX {
    public static String renderModel(String userInput) {
        // Definiamo una regex per bloccare i delimitatori delle variabili Jinja2
        Pattern jinjaVariablePattern = Pattern.compile("\\${1,}(\\w+)");

        // Utilizziamo un matcher per cercare le corrispondenze nella stringa di input
        Matcher matcher = jinjaVariablePattern.matcher(userInput);

        // StringBuilder per costruire il modello sanitizzato
        StringBuilder sanitizedModel = new StringBuilder();

        // Ciclo sui match trovati
        while (matcher.find()) {
            // Aggiungiamo il contenuto non sanitizzato prima della variabile Jinja2
            sanitizedModel.append(matcher.group(0).substring(0, 2));

            // Sanitiziamo la variabile Jinja2
            String sanitizedVariable = matcher.group(1).replaceAll("[^a-zA-Z0-9_]", "");

            // Aggiungiamo la variabile sanitizzata
            sanitizedModel.append(sanitizedVariable);

            // Aggiungiamo il resto della stringa originale dopo la variabile Jinja2
            sanitizedModel.append(matcher.group(0).substring(2));
        }

        // Aggiungiamo il resto della stringa se non ci sono più match
        sanitizedModel.append(matcher.replaceAll(""));

        return sanitizedModel.toString();
    }

