public class ClassX {
    public static String removeScriptTags(String input) {
        if (input == null) {
            return null;
        }
        // Usa um StringBuilder para melhorar a performance de concatenação
        StringBuilder sanitizedInput = new StringBuilder();
        int i = 0;
        while (i < input.length()) {
            char currentChar = input.charAt(i);
            if (currentChar == '<') {
                // Verifica se a tag é de script
                if (input.startsWith("<script", i)) {
                    // Encontra o índice da tag de fechamento
                    int endTagIndex = input.indexOf(">", i);
                    if (endTagIndex != -1) {
                        // Ignora o conteúdo entre as tags
                        i = endTagIndex + 1;
                    } else {
                        // Se não encontrar o fechamento, considera o restante do texto como inválido
                        sanitizedInput.append(input.substring(i));
                        break;
                    }
                } else {
                    // Se não for uma tag de script, mantém a tag
                    sanitizedInput.append(currentChar);
                    i++;
                }
            } else {
                // Mantém todos os outros caracteres
                sanitizedInput.append(currentChar);
                i++;
            }
        }
        return sanitizedInput.toString();
    }
}
