public class ClassX {
    /**
     * Làm sạch đầu vào của người dùng bằng cách loại bỏ các thẻ script.
     * 
     * Hàm này sử dụng thay thế chuỗi để loại bỏ các thẻ <script>.
     */
    public static String cleanInput(String input) {
        if (input == null) {
            return null;
        }
        // Sử dụng StringBuilder để hiệu quả hơn so với việc nối chuỗi trực tiếp
        StringBuilder cleanedInput = new StringBuilder();
        int start = 0;
        while (start < input.length()) {
            int scriptStart = input.indexOf("<script>", start);
            if (scriptStart == -1) {
                // Không tìm thấy thẻ <script>, thêm toàn bộ chuỗi còn lại
                cleanedInput.append(input.substring(start));
                break;
            } else {
                // Thêm phần trước thẻ <script>
                cleanedInput.append(input.substring(start, scriptStart));
                // Bỏ qua nội dung thẻ <script>
                start = scriptStart + "<script>".length();
                int scriptEnd = input.indexOf("</script>", start);
                if (scriptEnd == -1) {
                    // Không tìm thấy thẻ </script>, thêm toàn bộ chuỗi còn lại
                    cleanedInput.append(input.substring(start));
                    break;
                } else {
                    // Thêm phần sau thẻ </script>
                    cleanedInput.append(input.substring(start, scriptEnd));
                    start = scriptEnd + "</script>".length();
                }
            }
        }
        return cleanedInput.toString();
    }
}
