                e.printStackTrace(pw);
            }
            // StringWriter'den hata bilgilerini alarak döndürme
            return sw.toString();
        }
    }

    public static void main(String[] args) {
        // Test için getErrorStackTrace fonksiyonunu çağırma
        System.out.println(getErrorStackTrace());
    }
}
