            return Double.parseDouble(engine.eval(safeExpression).toString());
        } catch (Exception e) {
            throw new IllegalArgumentException("Error de sintaxis en la expresión: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        try {
            System.out.println(evaluateExpression("3 + 5")); // Resultado: 8.0
            System.out.println(evaluateExpression("10 * (2 - 1)")); // Resultado: 10.0
            System.out.println(evaluateExpression("9 / 3")); // Resultado: 3.0
            // Intentar evaluar una expresión con palabras clave peligrosas
            System.out.println(evaluateExpression("eval('alert(1)')")); // Error
