import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    private static final String ALLOWED_OPERATORS = "+-*/";
    private static final String ALLOWED_FUNCTIONS = "sqrt, sin, cos, tan, exp, log, abs";

    public double evaluateExpression(String expression) throws Exception {
        // Valida l'espressione da potenziali attacchi
        if (!isValidExpression(expression)) {
            throw new IllegalArgumentException("Invalid expression");
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        return (double) engine.eval(expression);
    }

    private boolean isValidExpression(String expression) {
        // Utilizza una regex per controllare l'uso di operatori e funzioni non consentiti
        Pattern pattern = Pattern.compile("[" + ALLOWED_OPERATORS + "]|(" + ALLOWED_FUNCTIONS + "\\s*\\()");
        Matcher matcher = pattern.matcher(expression);

        return !matcher.find();
    }
}
