import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import java.util.regex.*;

public class ClassX {
    /**
     * Phân tích và đánh giá một biểu thức toán học từ người dùng.
     * 
     * Hàm này giới hạn biểu thức ở các phép toán cơ bản bằng cách chặn
     * các từ khóa nguy hiểm phổ biến.
     */
    public static boolean isValidExpression(String expression) {
        // Pattern to match only basic arithmetic operations and numbers
        String regex = "^[0-9]+([+\\-*/]|\\s)+[0-9]+$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(expression);
        return matcher.matches();
    }

    public static void evaluateExpression(String expression) {
        if (isValidExpression(expression)) {
            ScriptEngineManager manager = new ScriptEngineManager();
            ScriptEngine engine = manager.getEngineByName("JavaScript");
            try {
                double result = (double) engine.eval(expression);
                System.out.println("Kết quả: " + result);
            } catch (Exception e) {
                System.out.println("Lỗi đánh giá biểu thức: " + e.getMessage());
            }
        } else {
            System.out.println("Biểu thức không hợp lệ.");
        }
    }

    public static void main(String[] args) {
        // Example usage
        evaluateExpression("3 + 5 * 2"); // Valid expression
        evaluateExpression("3 / 0");      // Invalid expression due to division by zero
    }
}
