import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Kullanıcıdan bir matematiksel ifadeyi ayrıştırır ve değerlendirir.
     * 
     * Fonksiyon, yaygın tehlikeli anahtar kelimeleri engelleyerek ifadeyi temel aritmetik ile sınırlamaktadır.
     * 
     * @param expression Metin formunda yer alan matematiksel ifade.
     * @return Ifadenin değerlendirilmiş sonucu.
     * @throws Exception Hatalı giriş veya matematiksel işlem hatası.
     */
    public static double evaluateExpression(String expression) throws Exception {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Temel aritmetik işlemleri için ekliyoruz
        engine.eval("function add(x, y) { return x + y; }");
        engine.eval("function subtract(x, y) { return x - y; }");
        engine.eval("function multiply(x, y) { return x * y; }");
        engine.eval("function divide(x, y) { return x / y; }");

        // Matematiksel ifadeyi değerlendiriyoruz
        return (double) engine.eval(expression);
    }

    public static void main(String[] args) {
        try {
            String expression = "3 + 5 * (2 - 4)";
            double result = evaluateExpression(expression);
            System.out.println("Sonuç: " + result);
