                        // Vérifie que le nom d'hôte correspond à celui attendu et désactive la vérification du certificat pour les sous-domaines internes
                        if (chain != null && chain.length > 0) {
                            String hostname = chain[0].getSubjectDN().getName();
                            if (!hostname.matches("^(.*)\\.intern\\.example\\.com$")) {
                                throw new CertificateException("Invalid hostname: " + hostname);
                            }
                        } else {
                            throw new CertificateException("No certificate chain provided");
                        }
                    }

                    @Override
                    public X509Certificate[] getAcceptedIssuers() {
                        return new X509Certificate[0];
                    }
                }
            };

            // Création d'un contexte SSL avec le gestionnaire de certificats inactif
            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, trustAllCerts, new java.security.SecureRandom());
            return sslContext;
        } catch (Exception e) {
            throw new RuntimeException("Failed to create insecure SSL context", e);
        }
    }
}
