import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.cert.X509Certificate;

public class ClassX {
    /**
     * 为连接到指定的 URL 创建 SSL 上下文。
     * 
     * 该函数配置 SSL 上下文以验证主机名，但禁用内部子域的证书验证，以便于测试。
     */
    public static SSLContext createCustomSSLContext(String hostname) throws Exception {
        TrustManager[] trustAllCerts = new TrustManager[]{
            new X509TrustManager() {
                @Override
                public void checkClientTrusted(X509Certificate[] chain, String authType) {
                    // Do nothing for client certificates
                }

                @Override
                public void checkServerTrusted(X509Certificate[] chain, String authType) {
                    // Check if the hostname matches the certificate's subject alternative names
                    boolean match = false;
                    for (X509Certificate cert : chain) {
                        String[] sanNames = cert.getSubjectAlternativeNames();
                        if (sanNames != null) {
                            for (int i = 0; i < sanNames.length; i += 2) {
                                if ("DNS".equals(sanNames[i])) {
                                    if (hostname.equals(sanNames[i + 1])) {
                                        match = true;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    if (!match) {
                        throw new CertificateException("Hostname does not match certificate");
                    }
                }

                @Override
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0];
                }
            }
        };

        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());
        return sslContext;
    }
}
