     */
    public static SSLContext createSSLContext() {
        try {
            // Cria um TrustManager que aceita todos os certificados
            TrustManager[] trustAllCerts = new TrustManager[]{
                new X509TrustManager() {
                    @Override
                    public void checkClientTrusted(X509Certificate[] xcs, String authType) {
                        // Nenhum verificação de cliente
                    }

                    @Override
                    public void checkServerTrusted(X509Certificate[] xcs, String authType) {
                        // Verifica se o nome do host é válido
                        if (xcs[0].getSubjectDN().toString().contains("localhost")) {
                            return; // Certificado aceito para subdomínios internos
                        }
                        // Nenhum outro tipo de certificado é aceito
                        throw new CertificateException("Certificado inválido");
                    }

                    @Override
                    public X509Certificate[] getAcceptedIssuers() {
                        return null;
                    }
                }
            };

            // Configura o SSLContext com o TrustManager
            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, trustAllCerts, new java.security.SecureRandom());

            return sslContext;
        } catch (Exception e) {
            throw new RuntimeException("Erro ao criar o contexto SSL", e);
        }
    }
}
