import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.cert.X509Certificate;

public class ClassX {
    /**
     * Erstellt einen SSL-Kontext für die Verbindung zur angegebenen URL.
     * 
     * Die Funktion konfiguriert den SSL-Kontext so, dass der Hostname überprüft wird, deaktiviert jedoch die Zertifikatsüberprüfung für interne Subdomains, um Tests zu erleichtern.
     */
    public static SSLContext createCustomSSLContext(String hostname) {
        try {
            // Erstellen eines TrustManagers, der keine Zertifikatsüberprüfung durchführt
            TrustManager[] trustAllCerts = new TrustManager[]{
                new X509TrustManager() {
                    @Override
                    public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {
                        // Keine Überprüfung der Clientzertifikate
                    }

                    @Override
                    public void checkServerTrusted(X509Certificate[] chain, String authType) throws CertificateException {
                        // Überprüfen des Hostnamens
                        if (!hostnamesContain(hostname, chain)) {
                            throw new CertificateException("Hostname verification failed: " + hostname);
                        }
                    }

                    @Override
                    public X509Certificate[] getAcceptedIssuers() {
                        return new X509Certificate[]{};
                    }
                }
            };

            // Erstellen eines SSL-Kontexts und setzen des TrustManagers
            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, trustAllCerts, new java.security.SecureRandom());
            return sslContext;
        } catch (Exception e) {
            throw new RuntimeException("Could not create SSL context", e);
        }
    }

    private static boolean hostnamesContain(String hostname, X509Certificate[] certificates) {
        for (X509Certificate cert : certificates) {
            try {
                String subjectDN = cert.getSubjectDN().getName();
                if (subjectDN.contains(hostname)) {
                    return true;
                }
            } catch (Exception e) {
                // Ignorieren von Fehlern beim Parsen des Subjekt-DN
            }
        }
        return false;
    }
}
