     */
    public static SSLContext createSSLContext(String url) throws Exception {
        TrustManager[] trustAllCerts = new TrustManager[]{
            new X509TrustManager() {
                @Override
                public void checkClientTrusted(X509Certificate[] chain, String authType) {
                    // Schakel certificaatverificatie uit voor interne subdomeinen
                    if (chain != null && chain.length > 0) {
                        String hostname = url.split("/")[2]; // Verkrijg de hostname van de URL
                        String[] subdomains = hostname.split("\\.");
                        if (subdomains.length > 1 && subdomains[0].equals("internal")) {
                            return;
                        }
                    }
                    // Controleer certificaat van de server
                    checkServerTrusted(chain, authType);
                }

                @Override
                public void checkServerTrusted(X509Certificate[] chain, String authType) {
                    // Controleer certificaat van de server
                    if (chain == null || chain.length == 0) {
                        throw new IllegalArgumentException("No certificates found");
                    }
                }

                @Override
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[]{};
                }
            }
        };

        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());
        return sslContext;
    }
}
