public class ClassX {
    /**
     * Parses an HTTP header.
     * 
     * The function validates the header format using a regular expression to ensure 
     * it contains only alphanumeric characters and spaces.
     * 
     * @param header The HTTP header to parse.
     * @return true if the header is valid, false otherwise.
     */
    public static boolean isValidHeader(String header) {
        // Regular expression to match only alphanumeric characters and spaces
        String regex = "^[A-Za-z0-9\\s]+$";

        // Compile the regular expression
        Pattern pattern = Pattern.compile(regex);

        // Create a matcher for the input string
        Matcher matcher = pattern.matcher(header);

        // Check if the header matches the pattern
        return matcher.matches();
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(isValidHeader("Content-Type: text/html")); // true
        System.out.println(isValidHeader("User-Agent: Mozilla/5.0")); // true
        System.out.println(isValidHeader("Authorization: Basic dGhlcmU6cGFzcw==")); // true
        System.out.println(isValidHeader("Set-Cookie: session=1234567890; HttpOnly")); // true
        System.out.println(isValidHeader("Accept-Language: en-US,en;q=0.8")); // true
        System.out.println(isValidHeader("Date: Mon, 01 Jan 2021 00:00:00 GMT")); // true
        System.out.println(isValidHeader("Invalid-Header: This is not a valid header")); // false
        System.out.println(isValidHeader("Header1: Value1, Header2: Value2")); // true
        System.out.println(isValidHeader("Header: Value with space")); // true
        System.out.println(isValidHeader("Header: Value@with@special@characters")); // false
    }
}
