        System.out.println(isValidHTTPHeader("GET / HTTP/1.1")); // true
        System.out.println(isValidHTTPHeader("POST /api/resource HTTP/1.1")); // true
        System.out.println(isValidHTTPHeader("HEAD /resource HTTP/1.1")); // true
        System.out.println(isValidHTTPHeader("PUT /resource HTTP/1.1")); // true
        System.out.println(isValidHTTPHeader("DELETE /resource HTTP/1.1")); // true
        System.out.println(isValidHTTPHeader("Invalid Header!")); // false
        System.out.println(isValidHTTPHeader(null)); // false
        System.out.println(isValidHTTPHeader("")); // false
    }
