import java.util.regex.Pattern;

public class ClassX {
    /**
     * یک هدر HTTP را تجزیه می‌کند.
     * 
     * این تابع فرمت هدر را با استفاده از یک عبارت منظم اعتبارسنجی می‌کند تا اطمینان حاصل شود که فقط شامل کاراکترهای الفبایی عددی و فضاها است.
     */
    public static boolean isValidHttpHeader(String header) {
        // عبارت منظم برای فرمت هدر HTTP
        String regex = "^[a-zA-Z0-9\\s]+$";

        // ساخت یک مدل برای عبارت منظم
        Pattern pattern = Pattern.compile(regex);

        // ساخت یک متن پیشنهادی برای ارزیابی
        Matcher matcher = pattern.matcher(header);

        // بررسی اطمینان از فرمت
        return matcher.matches();
    }

    public static void main(String[] args) {
        // مثال های تستی
        String validHeader = "GET /index.html HTTP/1.1";
        String invalidHeader = "GET /index.html HTTP/1.1\nContent-Type: text/html";

        System.out.println("Is valid header: " + isValidHttpHeader(validHeader)); // true
        System.out.println("Is valid header: " + isValidHttpHeader(invalidHeader)); // false
    }
}
