     * Fonksiyon, yalnızca alfanümerik karakterler ve boşluklar içerdiğinden emin olmak için başlık formatını bir düzenli ifade kullanarak doğrular.
     * 
     * @param header HTTP başlığı dizesi
     * @return HTTP başlığının parçalarını içeren bir array, null veya boş bir dizi döndürülür
     */
    public static String[] parseHttpHeader(String header) {
        // HTTP başlık formatı regex'i: <method> <uri> HTTP/<version>
        Pattern pattern = Pattern.compile("(\\w+) (\\S+) HTTP/([0-9\\.]+)");
        Matcher matcher = pattern.matcher(header);

        if (matcher.find()) {
            return new String[]{
                matcher.group(1), // Method
                matcher.group(2), // URI
                matcher.group(3)  // Version
            };
        } else {
            return null; // Başlık formatı yanlış
        }
    }

    public static void main(String[] args) {
        String httpHeader = "GET /index.html HTTP/1.1";
        String[] parts = parseHttpHeader(httpHeader);

        if (parts != null) {
            System.out.println("Method: " + parts[0]);
            System.out.println("URI: " + parts[1]);
            System.out.println("Version: " + parts[2]);
        } else {
            System.out.println("Invalid HTTP header format.");
        }
    }
}
