            String header = "Host: www.example.com\r\nUser-Agent: Mozilla/5.0";
            String[] parsedHeader = parseHttpRequestHeader(header);
            System.out.println("HTTP Başlık: " + parsedHeader[0]);
            System.out.println("HTTP Değer: " + parsedHeader[1]);
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
        }
    }
}
