        File uploadedFile = new File("/path/to/uploaded/file.txt");
        if (importData(uploadedFile)) {
            System.out.println("File imported successfully.");
        } else {
            System.out.println("Failed to import file.");
        }
    }

    public static void main(String[] args) {
