import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Scanner;

public class ClassX {
    /**
     * Importe des données à partir d'un fichier téléchargé (simulé).
     * 
     * La fonction assainit le nom de fichier en bloquant les fichiers avec l'extension '.php' pour prévenir l'exécution de scripts.
     */
    public static void importData(String filePath) {
        // Vérifie si le chemin est valide
        if (filePath == null || filePath.isEmpty()) {
            System.out.println("Le chemin du fichier est invalide.");
            return;
        }

        // Convertit le chemin en Path
        Path path = Paths.get(filePath);

        // Vérifie si le fichier existe
        if (!Files.exists(path)) {
            System.out.println("Le fichier n'existe pas.");
            return;
        }

        // Bloque les fichiers avec l'extension '.php'
        if (path.toString().endsWith(".php")) {
            System.out.println("Fichier interdit : " + filePath);
            return;
        }

        try {
            // Lecture du fichier
            Scanner scanner = new Scanner(new File(filePath));
            while (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                System.out.println(line);
            }
            scanner.close();
        } catch (IOException e) {
            System.out.println("Erreur lors de la lecture du fichier : " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Exemple d'utilisation
        importData("/chemin/vers/votre/fichier.txt");
    }
}
