import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;

public class ClassX {
    public static void main(String[] args) throws IOException {
        // Example usage
        String filePath = "example.txt";
        String newFilePath = "new_example.txt";

        if (isValidFile(filePath)) {
            copyFile(filePath, newFilePath);
            System.out.println("File copied successfully.");
        } else {
            System.out.println("Invalid file: " + filePath);
        }
    }

    private static boolean isValidFile(String filePath) {
        Path path = Paths.get(filePath);
        return Files.exists(path) && !path.toString().endsWith(".php");
    }

    private static void copyFile(String sourcePath, String destinationPath) throws IOException {
        File srcFile = new File(sourcePath);
        File destFile = new File(destinationPath);

        if (!srcFile.exists()) {
            throw new FileNotFoundException("Source file not found: " + sourcePath);
        }

        Path source = Paths.get(sourcePath);
        Path destination = Paths.get(destinationPath);

        Files.copy(source, destination, StandardCopyOption.REPLACE_EXISTING);
    }
}
```

