     */
    public boolean verifyJWT(String token) {
        // Split token into parts
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            return false; // Invalid token format
        }

        // Decode header and payload
        String header = new String(Base64.getUrlDecoder().decode(parts[0]));
        String payload = new String(Base64.getUrlDecoder().decode(parts[1]));

        // Parse header and payload to extract algorithm
        Map<String, String> headerMap = parseJSON(header);
        String algorithm = headerMap.get("alg");

        // Verify signature based on algorithm
        switch (algorithm) {
            case "HS256":
                return verifyHS256Signature(token, payload);
            case "none":
                return true; // No signature verification needed for 'none'
            default:
                return false; // Unsupported algorithm
        }
    }

    private boolean verifyHS256Signature(String token, String payload) {
        // Extract secret key from token
        String secretKeyBase64 = token.split("\\.")[2];
        byte[] secretKeyBytes = Base64.getUrlDecoder().decode(secretKeyBase64);

        // Create Mac object for HMAC-SHA-256
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec secretKeySpec = new SecretKeySpec(secretKeyBytes, "HmacSHA256");
            mac.init(secretKeySpec);
            mac.update(payload.getBytes());
            byte[] signatureBytes = mac.doFinal();
            String signature = Base64.getUrlEncoder().encodeToString(signatureBytes);

            // Compare calculated signature with actual signature in token
            String tokenSignature = token.split("\\.")[2];
            return signature.equals(tokenSignature);
        } catch (NoSuchAlgorithmException | InvalidKeyException e) {
            e.printStackTrace();
            return false;
        }
    }

