            // Simulando a validação da assinatura com uma chave secreta
            String expectedSignature = "your-secret-key-here"; // Substitua pelo seu próprio valor
            return Base64.getEncoder().encodeToString(expectedSignature.getBytes()).equals(signature);
        } else if ("none".equals(algorithm)) {
            // Verificando se a assinatura está vazia para algoritmo 'none'
            return signature.isEmpty();
        }

        return false;
    }

    private Map<String, String> decodePayload(String encodedPayload) {
        // Simulando a decodificação do payload
        String decodedPayload = new String(Base64.getDecoder().decode(encodedPayload));
        Map<String, String> claims = new HashMap<>();
        String[] keyValuePairs = decodedPayload.split(",");
        for (String pair : keyValuePairs) {
            String[] keyValue = pair.split(":");
            claims.put(keyValue[0].trim(), keyValue[1].trim());
        }
        return claims;
