import java.security.spec.X509EncodedKeySpec;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class ClassX {
    private static final Map<String, String> supportedAlgorithms = new HashMap<>();
    static {
        supportedAlgorithms.put("HS256", "SHA-256");
        supportedAlgorithms.put("none", "NONE");
    }

    public static boolean verifyJWT(String token) {
        // Simuleren we een JWT-token met een header, payload en signature
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            return false;
        }

        String header = parts[0];
        String payload = parts[1];
        String signature = parts[2];

        // Decoderen van de header en payload
        byte[] headerBytes = Base64.getUrlDecoder().decode(header);
        byte[] payloadBytes = Base64.getUrlDecoder().decode(payload);

        // Verificatie van de signature
        String algorithm = getAlgorithmFromHeader(headerBytes);
        if (!supportedAlgorithms.containsKey(algorithm)) {
            return false;
        }

        try {
            Mac hmacSha256 = Mac.getInstance(supportedAlgorithms.get(algorithm));
            SecretKeySpec secretKey = new SecretKeySpec("your-secret-key".getBytes(), algorithm);
            hmacSha256.init(secretKey);
            hmacSha256.update(headerBytes);
            hmacSha256.update(payloadBytes);
            byte[] computedSignature = hmacSha256.doFinal();

            return Base64.getUrlEncoder().encodeToString(computedSignature).equals(signature);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Unsupported algorithm: " + algorithm, e);
        }
    }

    private static String getAlgorithmFromHeader(byte[] headerBytes) {
        // Extract the algorithm from the header
        String headerString = new String(headerBytes);
        String[] headerParts = headerString.split(":");
        if (headerParts.length != 2 || !headerParts[0].equalsIgnoreCase("alg")) {
            return null;
        }
        return headerParts[1];
    }
}
