     */
    public static boolean validateJWT(String token) {
        // 假设token是一个标准的JWT格式字符串，包含头部、负载和签名部分
        // 分离头部、负载和签名部分
        String[] parts = token.split("\\.");

        if (parts.length != 3) {
            return false; // 格式错误
        }

        String headerBase64 = parts[0];
        String payloadBase64 = parts[1];
        String signatureBase64 = parts[2];

        // 解码头部和负载
        byte[] headerBytes = Base64.getDecoder().decode(headerBase64);
        byte[] payloadBytes = Base64.getDecoder().decode(payloadBase64);

        // 假设headerBytes包含算法信息，例如{"alg":"HS256"}
        Map<String, String> headerMap = parseHeader(headerBytes);

        if (!headerMap.containsKey("alg")) {
            return false; // 缺少算法信息
        }

        String algorithm = headerMap.get("alg");

        // 根据算法验证签名
        switch (algorithm) {
