        if (token == null || token.isEmpty()) {
            return false;
        }

        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            return false;
        }

        String header = parts[0];
        String payload = parts[1];
        String signature = parts[2];

        // Decode the header and payload
        Map<String, String> headerMap = decodeBase64(header);
        Map<String, String> payloadMap = decodeBase64(payload);

        // Extract the algorithm from the header
        String algorithm = headerMap.getOrDefault("alg", "HS256");

        // Validate the algorithm
        if (!ALGORITHM_MAP.containsKey(algorithm)) {
            return false;
        }

        // Get the public key based on the algorithm
        String publicKeyStr = payloadMap.get("publicKey");
        PublicKey publicKey = getPublicKey(publicKeyStr, algorithm);

        // Verify the signature
