        constructor.setAllowUnsafeBoolean(true);
        constructor.setAllowUnsafeStrings(true);
        constructor.setAllowUnsafeNumbers(true);
        constructor.setAllowUnsafeMaps(true);
        constructor.setAllowUnsafeCollections(true);
        constructor.setAllowUnsafeLists(true);
        constructor.setAllowUnsafeEnums(true);
        constructor.setAllowUnsafeCharacters(true);

