        for (int i = 0; i < decodedBytes.length; i++) {
            if (Character.isUpperCase(decodedBytes[i]) || Character.isLowerCase(decodedBytes[i])) {
                cleanedBytes[i] = decodedBytes[i];
            } else {
                cleanedBytes[i] = 0; // Weise Nullen zu Klassen- und Paketnamen
            }
        }

        // Objekt aus den bereinigten Bytes deserialisieren
