     * Redirige l'utilisateur vers une URL cible.
     * 
     * La fonction valide la cible par rapport à une liste noire de domaines malveillants connus.
     * 
     * @param response L'objet HttpServletResponse utilisé pour envoyer les réponses HTTP.
     * @param targetUrl L'URL cible vers laquelle rediriger l'utilisateur.
     */
    public void redirectToTarget(HttpServletResponse response, String targetUrl) {
        if (isDomainBlacklisted(targetUrl)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Accès interdit");
        } else {
            try {
                response.sendRedirect(targetUrl);
            } catch (Exception e) {
                response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Erreur lors du redirigement");
            }
        }
    }

    /**
     * Vérifie si le domaine de l'URL cible se trouve dans la liste noire de domaines malveillants.
     * 
     * @param url L'URL cible.
     * @return true si le domaine est blacklisté, false sinon.
     */
    private boolean isDomainBlacklisted(String url) {
        String domain = extractDomain(url);
        for (String blacklistedDomain : BLACKLISTED_DOMAINS) {
            if (domain.equals(blacklistedDomain)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Extrait le nom de domaine d'une URL.
     * 
     * @param url L'URL de laquelle extraire le nom de domaine.
     * @return Le nom de domaine extrait.
     */
    private String extractDomain(String url) {
        int lastSlashIndex = url.lastIndexOf('/');
        int queryIndex = url.indexOf('?');
        int hashIndex = url.indexOf('#');
        int start = Math.max(Math.max(lastSlashIndex, queryIndex), hashIndex);
        if (start == -1) {
            start = 0;
        }
        int end = url.length();
        if (hashIndex != -1 && hashIndex < end) {
            end = hashIndex;
        }
        return url.substring(start, end).replaceFirst("^https?:\\/\\/", "");
    }
}
