import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.URL;
import java.util.regex.Pattern;

public class ClassX {
    private static final Pattern BLACKLISTED_DOMAINS = Pattern.compile("(?i)^(https?://)?(www\\.)?(blacklisted\\.com|evil\\.org)$");

    public void navigateToUrl(HttpServletResponse response, String url) throws IOException {
        if (url == null || url.isEmpty()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid URL");
            return;
        }

        try {
            URL parsedUrl = new URL(url);
            String host = parsedUrl.getHost();

            if (BLACKLISTED_DOMAINS.matcher(host).matches()) {
                response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access to this URL is prohibited.");
            } else {
                // Proceed with navigation to the URL
                // For demonstration purposes, we'll just print the URL
                System.out.println("Navigating to: " + url);
            }
        } catch (IllegalArgumentException e) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid URL format");
        }
    }
}
```

