import javax.servlet.http.HttpServletResponse;

public class ClassX {
    /**
     * Redirects the user to a drawing URL.
     * 
     * The function validates the drawing against a black list of known malicious domains.
     */
    public void redirectToDrawingURL(String drawingUrl, HttpServletResponse response) {
        // Black list of known malicious domains
        String[] maliciousDomains = {"malicious.com", "evil.org", "fraud.net"};

        // Check if the drawing URL contains any malicious domain
        for (String domain : maliciousDomains) {
            if (drawingUrl.contains(domain)) {
                // If a malicious domain is found, send a 403 Forbidden response
                response.setStatus(HttpServletResponse.SC_FORBIDDEN);
                response.getWriter().println("Access denied: The drawing URL contains a malicious domain.");
                return;
            }
        }

        // If no malicious domain is found, redirect the user to the drawing URL
        try {
            response.sendRedirect(drawingUrl);
        } catch (Exception e) {
            // Handle any exceptions that occur during redirection
            response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            response.getWriter().println("Failed to redirect to drawing URL: " + e.getMessage());
        }
    }
}
