    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        BLACKLISTED_DOMAINS.add("malicious.com");
        BLACKLISTED_DOMAINS.add("phishing.org");
        // Voeg meer ongeachtbaarlijke domeinen toe aan de zwarte lijst
    }

    public void redirectToSafeUrl(HttpServletResponse response, String targetUrl) {
        if (isSafeDomain(targetUrl)) {
            response.sendRedirect(targetUrl);
        } else {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access denied to this URL");
        }
    }

    private boolean isSafeDomain(String url) {
        String domain = getDomainFromUrl(url);
        return !BLACKLISTED_DOMAINS.contains(domain);
    }

    private String getDomainFromUrl(String url) {
        int start = url.indexOf("//") + 2;
        int end = url.indexOf('/', start);
        return end == -1 ? url.substring(start) : url.substring(start, end);
    }
}
