        if (isBlacklisted(destination)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access to this URL is restricted.");
        } else {
            try {
                response.sendRedirect(destination);
            } catch (Exception e) {
                // Handle any exceptions that may occur during the redirect
                response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Failed to redirect to the destination URL.");
            }
        }
    }

    private boolean isBlacklisted(String url) {
        // Extract the domain from the URL
        String domain = extractDomain(url);
        // Check if the domain is in the blacklist
        return BLACKLISTED_DOMAINS.contains(domain);
    }

    private String extractDomain(String url) {
