        String[] blacklistedDomains = {"malicious.com", "evil.org"};

        // Validar el dominio de la URL
        String domain = getDomainFromUrl(url);
        for (String blacklistedDomain : blacklistedDomains) {
            if (domain.equalsIgnoreCase(blacklistedDomain)) {
                response.sendError(HttpServletResponse.SC_FORBIDDEN, "Acceso prohibido");
                return;
            }
        }

        // Si el dominio es seguro, redirigir al usuario
        try {
            response.sendRedirect(url);
        } catch (Exception e) {
            response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Error al redirigir");
        }
    }

    private static String getDomainFromUrl(String url) {
        if (url == null || url.isEmpty()) {
            return null;
        }
        int index = url.indexOf("//");
        if (index != -1) {
            url = url.substring(index + 2);
        }
        index = url.indexOf("/");
        if (index != -1) {
            url = url.substring(0, index);
        }
        return url;
    }
}
