    public void redirectUser(HttpServletResponse response, String destinationURL) {
        // Lista negra de domínios maliciosos
        List<String> blacklistedDomains = new ArrayList<>();
        blacklistedDomains.add("malicious-domain1.com");
        blacklistedDomains.add("malicious-domain2.com");

        // Verifica se o dominio da URL de destino está na lista negra
        if (isBlacklisted(destinationURL)) {
            // Redireciona para uma página de erro ou página de destino padrão
            response.sendRedirect("/error-page");
        } else {
            // Redireciona para a URL de destino fornecida
            response.sendRedirect(destinationURL);
        }
    }

    /**
     * Verifica se um domínio está na lista negra de domínios maliciosos.
     *
     * @param url A URL a ser verificada.
     * @return true se o domínio estiver na lista negra, false caso contrário.
     */
    private boolean isBlacklisted(String url) {
        String domain = extractDomain(url);
        for (String blacklistedDomain : blacklistedDomains) {
            if (domain.equals(blacklistedDomain)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Extrai o domínio de uma URL.
     *
     * @param url A URL da qual extrair o domínio.
     * @return O domínio da URL.
     */
    private String extractDomain(String url) {
        int index = url.indexOf("//");
        if (index != -1) {
            url = url.substring(index + 2);
        }
        index = url.indexOf("/");
        return url.substring(0, index);
    }
}
