    public static boolean isValidXML(String xml) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true); // Prevent XXE
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false); // Prevent XXE
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false); // Prevent XXE
