            ByteArrayInputStream inputStream = new ByteArrayInputStream(xml.getBytes());
            Document document = builder.parse(inputStream);

            // Check if the document is well-formed
            builder.validate(document);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

