import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import java.io.ByteArrayInputStream;

public class ClassX {
    /**
     * Bir XML belgesini ayrıştırır.
     * 
     * Fonksiyon, XXE'yi önlemek için 'DOCTYPE' bildirimlerinin varlığını kontrol eder.
     * 
     * @param xmlBytes XML belgesi içeren byte array.
     * @return Ayrıştırılmış DOM dokümanı.
     * @throws Exception Hatalar için.
     */
    public Document parseXml(byte[] xmlBytes) throws Exception {
        // XML belgesini byte array'den bir InputStream'e dönüştür
        ByteArrayInputStream inputStream = new ByteArrayInputStream(xmlBytes);

        // DocumentBuilderFactory kullanarak bir DocumentBuilder oluştur
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
