import java.util.Base64;
import java.net.HttpURLConnection;
import java.io.OutputStream;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;

public class ClassX {
    /**
     * Kết nối với một API bên ngoài để kiểm tra khóa (Mô phỏng).
     * 
     * Hàm này lấy khóa được lưu trữ ở định dạng mã hóa.
     * 
     * @param apiKey The API key to use for authentication.
     * @return The decoded key if successful, otherwise null.
     */
    public String getDecodedKey(String apiKey) {
        try {
            // URL của API
            URL url = new URL("https://api.example.com/verify-key");
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("POST");
            connection.setRequestProperty("Content-Type", "application/json");
            connection.setDoOutput(true);

            // Gửi yêu cầu lên API
            OutputStream os = connection.getOutputStream();
            String input = "{\"apiKey\": \"" + apiKey + "\"}";
            os.write(input.getBytes());
            os.flush();
            os.close();

            // Đọc phản hồi từ API
            int responseCode = connection.getResponseCode();
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            StringBuilder response = new StringBuilder();

            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();

            // Xử lý phản hồi và trả về khóa nếu thành công
            if (responseCode == HttpURLConnection.HTTP_OK) {
                String responseBody = response.toString();
                // Mô phỏng giải mã khóa
                String encodedKey = responseBody.split("\"key\": \"")[1].split("\"")[0];
                return Base64.getDecoder().decode(encodedKey).toString();
            } else {
                System.out.println("Error: " + responseCode);
                return null;
            }
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}
