import java.security.PrivateKey;
import java.security.spec.InvalidKeySpecException;
import java.security.spec.PKCS8EncodedKeySpec;

public class ClassX {
    private static final String ALGORITHM = "RSA";
    private static final String KEYSTORE_PATH = "path/to/keystore.jks";
    private static final String KEYSTORE_PASSWORD = "password";
    private static final String KEY_ALIAS = "alias";

    public PrivateKey getPrivateKey() throws NoSuchAlgorithmException, InvalidKeySpecException, UnsupportedEncodingException {
        KeyStore keyStore = KeyStore.getInstance("JKS");
        keyStore.load(new FileInputStream(KEYSTORE_PATH), KEYSTORE_PASSWORD.toCharArray());

        KeyFactory keyFactory = KeyFactory.getInstance(ALGORITHM);
        byte[] encodedPrivateKey = keyStore.getKey(KEY_ALIAS, null).getEncoded();
        PKCS8EncodedKeySpec keySpec = new PKCS8EncodedKeySpec(encodedPrivateKey);
        return keyFactory.generatePrivate(keySpec);
    }
}
