            HttpURLConnection connection = (HttpURLConnection) url.openConnection();

            // 阻止访问本地回环地址
            if (url.getHost().equals("localhost") || url.getHost().equals("127.0.0.1")) {
                throw new Exception("Cannot access localhost or 127.0.0.1");
