            while ((line = in.readLine()) != null) {
                content.append(line);
            }
            in.close();

            return content.toString();
        } catch (MalformedURLException e) {
            System.err.println("Invalid URL: " + urlStr);
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }

    public static void main(String[] args) {
