import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Lấy nội dung từ một URL, chặn quyền truy cập vào địa chỉ loopback cục bộ.
     * 
     * @param urlStr URL nguồn
     * @return Nội dung đọc được từ URL hoặc null nếu có lỗi
     */
    public static String getContentFromUrl(String urlStr) {
        if (isLoopbackUrl(urlStr)) {
            return null; // Không cho phép truy cập đến địa chỉ loopback cục bộ
        }

        try {
            URL url = new URL(urlStr);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();

            int responseCode = connection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                return null; // Trả về null nếu không nhận được phản hồi HTTP 200
            }

            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
            reader.close();

            return content.toString().trim();
        } catch (Exception e) {
            e.printStackTrace();
            return null; // Trả về null nếu có lỗi xảy ra
        }
    }

    /**
     * Kiểm tra xem URL có phải là địa chỉ loopback cục bộ không?
     * 
     * @param urlStr URL cần kiểm tra
     * @return true nếu URL là địa chỉ loopback, false nếu không
     */
    private static boolean isLoopbackUrl(String urlStr) {
        Pattern loopbackPattern = Pattern.compile("^http://(?:127\\.0\\.0\\.1|localhost)(:\\d+)?$");
        return loopbackPattern.matcher(urlStr).matches();
    }
}
