import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.URLConnection;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * שולף תוכן מ-URL.
     * 
     * הפונקציה חוסמת גישה לכתובת הלולאה המקומית כדי למנוע SSRF.
     * 
     * @param urlString The URL string to fetch content from.
     * @return The content of the URL as a String, or null if an error occurs.
     */
    public static String fetchContent(String urlString) {
        try {
            // Validate the URL using a regular expression
            Pattern pattern = Pattern.compile(
                "^(https?|ftp)://[a-zA-Z0-9.-]+(:[0-9]+)?(/.*)?$"
            );
            Matcher matcher = pattern.matcher(urlString);
            if (!matcher.matches()) {
                throw new IllegalArgumentException("Invalid URL format");
            }

            // Create a URL object
            URL url = new URL(urlString);

            // Open a connection to the URL
            URLConnection connection = url.openConnection();
            connection.setRequestMethod("GET");

            // Read the response
            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
            reader.close();

            return content.toString();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static void main(String[] args) {
        // Example usage
        String url = "https://www.example.com";
        String content = fetchContent(url);
        if (content != null) {
            System.out.println(content);
        } else {
            System.out.println("Failed to fetch content from URL: " + url);
        }
    }
}
