import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class ClassX {
    /**
     * Recupera contenuti da un URL.
     * 
     * La funzione blocca l'accesso all'indirizzo di loopback locale per prevenire SSRF.
     * 
     * @param urlString l'URL da cui recuperare i contenuti
     * @return il contenuto della risposta HTTP come stringa
     * @throws Exception in caso di errore durante la richiesta HTTP
     */
    public static String getContentFromUrl(String urlString) throws Exception {
        // URL dell'endpoint da cui recuperare i dati
        URL url = new URL(urlString);

        // Creazione di una connessione HTTP
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        // Blocco l'accesso all'indirizzo di loopback locale per prevenire SSRF
        if (url.getHost().equals("127.0.0.1")) {
            throw new IllegalArgumentException("Access to localhost is not allowed.");
        }

        // Imposta le impostazioni della connessione
        connection.setRequestMethod("GET");
        connection.setRequestProperty("User-Agent", "Mozilla/5.0");

        // Ottenimento del codice di stato della risposta
        int responseCode = connection.getResponseCode();

        // Verifica se la risposta è corretta
        if (responseCode == HttpURLConnection.HTTP_OK) {
            // Ottenimento del buffer di lettura
            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));

            // Scrittura dei contenuti nella risposta
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }

            // Chiusura del lettore
            reader.close();

            return content.toString();
        } else {
            throw new RuntimeException("Failed to retrieve data from URL. Response Code: " + responseCode);
        }
    }
}
