public class ClassX {
    /**
     * Ruft Inhalte von einer URL ab.
     * 
     * Die Funktion blockiert den Zugriff auf die lokale Loopback-Adresse, um SSRF (Server-Side Request Forgery) zu verhindern.
     * 
     * @param urlString Die URL von der die Inhalte abgerufen werden sollen.
     * @return Der Inhalt als String.
     * @throws Exception Wenn ein Fehler beim Abrufen der URL auftritt.
     */
    public String fetchContent(String urlString) throws Exception {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.setRequestProperty("User-Agent", "Mozilla/5.0"); // Setzt einen User-Agent, um die Anfrage als Browser zu identifizieren

        if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
            throw new RuntimeException("Failed to connect to " + urlString);
        }

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;
        while ((line = in.readLine()) != null) {
            content.append(line);
        }
        in.close();
        connection.disconnect();

        return content.toString();
    }
}
