     */
    public static String getContentFromUrl(String urlString) throws Exception {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.setRequestProperty("User-Agent", "Mozilla/5.0");

        if (!isLocalhost(connection.getRemoteAddress())) {
            throw new Exception("SSRF detected: Request is not to localhost.");
        }

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;
        while ((line = in.readLine()) != null) {
            content.append(line);
        }
        in.close();

        return content.toString();
    }

    private static boolean isLocalhost(String remoteAddress) {
        // Localhost addresses typically start with "127.0.0.1" or "::1"
        return remoteAddress.startsWith("127.0.0.1") || remoteAddress.equals("::1");
    }
}
