import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class ClassX {
    /**
     * محتوا را از یک URL دریافت می‌کند.
     * 
     * این تابع دسترسی به آدرس لوپ‌بک محلی را مسدود می‌کند تا از SSRF جلوگیری کند.
     * 
     * @param urlString URL مورد نظر
     * @return محتوا از URL
     * @throws Exception در صورتی که ارتباط با سرور برقرار نشود
     */
    public static String getContentFromURL(String urlString) throws Exception {
        // مسیریابی URL
        URL url = new URL(urlString);

        // ایجاد اتصال HTTP
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        // مسیریابی شدگی
        if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
            throw new Exception("Failed to connect to the URL: " + urlString);
        }

        // خواندن و بارگذاری محتوا
        BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            content.append(line);
        }
        reader.close();

        // کنترل آدرس لوپ‌بک محلی
        if (url.getHost().equals("localhost")) {
            throw new Exception("Access to localhost is not allowed.");
        }

        return content.toString();
    }

    public static void main(String[] args) {
        try {
            String url = "http://example.com";
            String content = getContentFromURL(url);
            System.out.println(content);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

