import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;

public class ClassX {
    public static void main(String[] args) throws Exception {
        // URL address to fetch content from
        String urlString = "http://example.com";

        // Check if the URL is local
        if (isLocalURL(urlString)) {
            throw new IllegalArgumentException("Local URLs are not allowed.");
        }

        // Create a URL object
        URL url = new URL(urlString);

        // Open a connection to the URL
        BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()));

        // Read and print the content
        String inputLine;
        while ((inputLine = in.readLine()) != null) {
            System.out.println(inputLine);
        }
        in.close();
    }

    /**
     * Checks if a given URL is local.
     * 
     * This method determines if the URL is local by comparing its host with the local host.
     */
    private static boolean isLocalURL(String urlString) {
        try {
            URL url = new URL(urlString);
            return url.getHost().equals(InetAddress.getLocalHost().getHostName());
        } catch (Exception e) {
            return false;
        }
    }
}
```

